  assert.equal((await h.payment('p')).status, 'failed');
  assert.equal((await pendingFor(h, 'p')).length, 2);

  await h.authorize('q', 1);
  await h.timedOut('q');
  const qs = await pendingFor(h, 'q');
  await h.completeEffect(qs[1].id, 'failed');
  assert.equal((await h.payment('q')).status, 'declined');
  await h.completeEffect(qs[0].id, 'ok');
  assert.equal((await h.payment('q')).status, 'declined');

